# region: render
def render(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: emit
def emit(xs, offset=1):
    return [v + offset for v in xs[1:]]

# region: fold
def fold(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: gather
def gather(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: sift
def sift(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return sift(gather(fold(emit(render(raw)))))

